/* ========================================
   ClipCast — Global Styles
   ======================================== */

:root {
  --primary: #1868DB;
  --primary-dark: #1457b8;
  --accent: #FF613D;
  --accent-dark: #e55533;
  --dark: #292A2E;
  --gray-900: #1a1a2e;
  --gray-800: #2d2d3a;
  --gray-700: #4a4a5a;
  --gray-600: #6b6b7b;
  --gray-500: #8a8a9a;
  --gray-400: #a8a8b8;
  --gray-300: #c8c8d4;
  --gray-200: #e4e4ec;
  --gray-100: #f2f2f7;
  --gray-50: #fafafc;
  --white: #ffffff;
  --success: #22c55e;
  --warning: #f59e0b;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.12);
  --shadow-xl: 0 24px 48px rgba(0,0,0,0.16);
  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--dark);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--primary-dark);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ========================================
   Typography
   ======================================== */

h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }

.text-gradient {
  background: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.text-center { text-align: center; }
.text-muted { color: var(--gray-600); }

/* ========================================
   Buttons
   ======================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-dark);
  color: var(--white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
}

.btn-accent:hover {
  background: var(--accent-dark);
  color: var(--white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--dark);
  border: 2px solid var(--gray-300);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--gray-700);
}

.btn-ghost:hover {
  color: var(--dark);
  background: var(--gray-100);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1.125rem;
}

/* ========================================
   Navigation
   ======================================== */

.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--dark);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.1rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  color: var(--gray-700);
  font-weight: 500;
  font-size: 0.95rem;
}

.nav-links a:hover {
  color: var(--dark);
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--dark);
  transition: var(--transition);
}

/* ========================================
   Sections
   ======================================== */

.section {
  padding: 96px 0;
}

.section-alt {
  background: var(--gray-50);
}

.section-header {
  max-width: 640px;
  margin: 0 auto 64px;
  text-align: center;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--gray-600);
}

/* ========================================
   Hero
   ======================================== */

.hero {
  padding: 80px 0 96px;
  position: relative;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, #f8f6ff 0%, var(--white) 100%);
  z-index: -1;
}

.hero-bg::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(124,58,237,0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.hero-content h1 {
  margin-bottom: 20px;
  color: var(--dark);
}

.hero-content p {
  font-size: 1.25rem;
  color: var(--gray-600);
  margin-bottom: 32px;
  max-width: 520px;
}

.hero-buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
}

.hero-mockup {
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  padding: 24px;
  border: 1px solid var(--gray-200);
  position: relative;
}

.mockup-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
}

.mockup-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.mockup-dot.red { background: #ff5f56; }
.mockup-dot.yellow { background: #ffbd2e; }
.mockup-dot.green { background: #27c93f; }

.mockup-video {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #e0e7ff 0%, #c7b8ff 100%);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.play-btn {
  width: 64px;
  height: 64px;
  background: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
  cursor: pointer;
  transition: var(--transition);
}

.play-btn:hover {
  transform: scale(1.08);
}

/* ========================================
   Logo Bar
   ======================================== */

.logo-bar {
  padding: 48px 0;
  border-top: 1px solid var(--gray-200);
  border-bottom: 1px solid var(--gray-200);
}

.logo-bar p {
  text-align: center;
  color: var(--gray-500);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 24px;
}

.logos {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 48px;
  flex-wrap: wrap;
}

.logo-item {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--gray-400);
  transition: var(--transition);
}

.logo-item:hover {
  color: var(--gray-600);
}

/* ========================================
   Feature Cards
   ======================================== */

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 48px;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.feature-label {
  display: inline-block;
  padding: 4px 12px;
  background: var(--accent);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 100px;
  margin-bottom: 16px;
}

.feature-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: center;
}

.feature-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* ========================================
   Use Cases
   ======================================== */

.use-case-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  text-align: center;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.use-case-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.use-case-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  font-size: 1.5rem;
}

/* ========================================
   Features Grid
   ======================================== */

.features-grid .feature-item {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 28px;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.features-grid .feature-item:hover {
  box-shadow: var(--shadow-md);
}

.feature-item-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  margin-bottom: 16px;
  font-size: 1.25rem;
}

/* ========================================
   Stats
   ======================================== */

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.stat-card {
  text-align: center;
  padding: 48px 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.stat-number {
  font-size: 3.5rem;
  font-weight: 800;
  background: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1;
  margin-bottom: 12px;
}

.stat-label {
  color: var(--gray-600);
  font-size: 1rem;
}

/* ========================================
   Testimonials
   ======================================== */

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.testimonial-card:hover {
  box-shadow: var(--shadow-md);
}

.testimonial-quote {
  font-size: 1rem;
  color: var(--gray-700);
  margin-bottom: 24px;
  line-height: 1.7;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 14px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
  font-size: 0.875rem;
}

.testimonial-name {
  font-weight: 700;
  color: var(--dark);
  font-size: 0.9375rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* ========================================
   Pricing
   ======================================== */

.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 100px;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-knob {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active .toggle-knob {
  transform: translateX(24px);
}

.toggle-label {
  font-weight: 600;
  color: var(--gray-600);
  cursor: pointer;
}

.toggle-label.active {
  color: var(--dark);
}

.save-badge {
  display: inline-block;
  padding: 4px 10px;
  background: #dcfce7;
  color: #166534;
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 100px;
  margin-left: 8px;
}

.pricing-slider {
  max-width: 500px;
  margin: 0 auto 48px;
  text-align: center;
}

.slider-label {
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--gray-700);
}

.slider-input {
  width: 100%;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--gray-200);
  border-radius: 100px;
  outline: none;
}

.slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px;
  height: 22px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: var(--transition);
}

.slider-input::-webkit-slider-thumb:hover {
  transform: scale(1.15);
}

.slider-value {
  margin-top: 8px;
  font-weight: 700;
  color: var(--primary);
  font-size: 1.125rem;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 64px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  border: 2px solid var(--gray-200);
  transition: var(--transition);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: 0 0 0 4px rgba(24,104,219,0.08);
}

.popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  padding: 4px 14px;
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 100px;
}

.pricing-card h3 {
  margin-bottom: 8px;
}

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  margin-bottom: 4px;
}

.pricing-price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-500);
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: 24px;
  min-height: 40px;
}

.pricing-features {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-features li {
  padding: 6px 0;
  font-size: 0.875rem;
  color: var(--gray-700);
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.pricing-features li::before {
  content: '✓';
  color: var(--success);
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

/* Comparison Table */
.comparison-table-wrapper {
  overflow-x: auto;
  margin-bottom: 64px;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.comparison-table th,
.comparison-table td {
  padding: 16px 20px;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.comparison-table th {
  font-weight: 700;
  color: var(--dark);
  background: var(--gray-50);
  white-space: nowrap;
}

.comparison-table th:first-child {
  border-radius: var(--radius-md) 0 0 0;
}

.comparison-table th:last-child {
  border-radius: 0 var(--radius-md) 0 0;
}

.comparison-table td {
  color: var(--gray-700);
}

.comparison-table tr:hover td {
  background: var(--gray-50);
}

.check {
  color: var(--success);
  font-weight: 700;
}

.dash {
  color: var(--gray-400);
}

/* FAQ */
.faq-list {
  max-width: 768px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--dark);
  cursor: pointer;
  text-align: left;
  transition: var(--transition);
}

.faq-question:hover {
  color: var(--primary);
}

.faq-icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-item.active .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* ========================================
   Blog Cards
   ======================================== */

.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.blog-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.blog-thumb {
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #e0e7ff 0%, #c7b8ff 100%);
}

.blog-content {
  padding: 28px;
}

.blog-content h3 {
  margin-bottom: 12px;
  font-size: 1.125rem;
}

.blog-content p {
  color: var(--gray-600);
  font-size: 0.9375rem;
  margin-bottom: 16px;
}

/* ========================================
   CTA Banner
   ======================================== */

.cta-banner {
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  z-index: -1;
}

.cta-banner h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: 32px;
}

.cta-banner .btn-accent {
  background: var(--white);
  color: var(--primary);
}

.cta-banner .btn-accent:hover {
  background: var(--gray-100);
  color: var(--primary-dark);
}

/* ========================================
   Footer
   ======================================== */

.footer {
  background: var(--dark);
  color: var(--gray-400);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(5, 1fr);
  gap: 48px;
  margin-bottom: 64px;
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 280px;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--gray-400);
  font-size: 0.9375rem;
  transition: var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
